/*
 * A184118  Upper s(n)-Wythoff sequence, where s(n) = 2n + 1.
 * https://oeis.org/A184118
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A184117(n) + (2*n + 1) where A184117(n) is generated by
 *            the s(n)-Wythoff construction with s(n) = 2*n + 1
 * Range:     u8 n <= 74, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>

/* state for the sequence */
static idx_t max_computed = 0;           /* largest n that has been computed */
static idx_t next_candidate = 1;          /* smallest integer not yet used */

static seq_t *lower = NULL;              /* lower part of the pairs (1‑indexed) */
static idx_t lower_cap = 0;               /* capacity of lower array */

static uint8_t *used = NULL;             /* bit array of used integers */
static idx_t used_cap = 0;                /* number of bits allocated */

/* --- bit operations for the used array ---------------------------------- */
static inline bool test_used(idx_t x)
{
    return (used[x >> 3] & (1U << (x & 7))) != 0;
}

static inline void set_used(idx_t x)
{
    used[x >> 3] |= (1U << (x & 7));
}

/* enlarge the used bitset so that it can hold index up_to  (inclusive) */
static void enlarge_used(idx_t up_to)
{
    idx_t new_cap = used_cap > 0 ? used_cap : 128;
    while (new_cap <= up_to) new_cap <<= 1;
    uint8_t *new_arr = (uint8_t *)malloc((new_cap >> 3) + 1);
    if (!new_arr) exit(EXIT_FAILURE);
    memset(new_arr, 0, (new_cap >> 3) + 1);
    if (used) {
        size_t old_bytes = (used_cap >> 3) + 1;
        memcpy(new_arr, used, old_bytes);
        free(used);
    }
    used = new_arr;
    used_cap = new_cap;
}

/* enlarge the lower array so that it can hold index needed  (1‑based) */
static void ensure_lower_cap(idx_t needed)
{
    if (needed <= lower_cap) return;
    idx_t new_cap = lower_cap > 0 ? lower_cap : 16;
    while (new_cap < needed) new_cap <<= 1;
    seq_t *new_arr = (seq_t *)realloc(lower, (new_cap + 1) * sizeof(seq_t));
    if (!new_arr) exit(EXIT_FAILURE);
    if (new_cap > lower_cap) {
        memset(new_arr + lower_cap + 1,
               0,
               (new_cap - lower_cap) * sizeof(seq_t));
    }
    lower = new_arr;
    lower_cap = new_cap;
}

/* compute sequence values up to n (inclusive) */
static void ensure_n(idx_t n)
{
    if (max_computed >= n) return;
    while (max_computed < n) {
        idx_t k = max_computed + 1;             /* next index to compute   */
        idx_t sk = 2 * k + 1ULL;                /* s(k) = 2k + 1           */

        /* find smallest unused integer */
        idx_t x = next_candidate;
        for (;;) {
            if (x >= used_cap) enlarge_used(x);
            if (!test_used(x)) break;
            ++x;
        }

        /* the upper partner */
        idx_t u = x + sk;
        if (u >= used_cap) enlarge_used(u);

        /* mark both numbers as used */
        set_used(x);
        set_used(u);

        /* store the lower part */
        ensure_lower_cap(k);
        lower[k] = (seq_t)x;

        /* update for next search */
        next_candidate = x + 1;
        ++max_computed;
    }
}

/* public function for the OEIS sequence */
seq_t a(idx_t n)
{
    if (n < 1) return 0;
    ensure_n(n);
    /* a(n) = lower(n) + (2*n + 1) */
    seq_t s = (seq_t)(2 * n) + 1;
    return lower[n] + s;
}
